<script>
import opportunityLayout from '@/Layouts/opportunityLayout';
export default { layout: opportunityLayout };
</script>
<script setup>
import { computed, ref } from 'vue';
import { Link, router, usePage, useForm } from '@inertiajs/vue3';
import { ArrowUpRight, Bookmark, Check, Copy, Download } from '@lucide/vue';
import CompanyLogo from '@/Components/Ui/CompanyLogo.vue';
import RoleCard from '@/Components/Internship/RoleCard.vue';
import { markOpened, openedAt, isSaved, toggleSaved } from '@/composables/useOpportunityActivity';
const props = defineProps({ internship: { type: Object, required: true }, related: { type: [Object, Array], default: () => ({ data: [] }) }, translation: { type: String, default: null } });
const relatedListings = computed(() => Array.isArray(props.related) ? props.related : props.related?.data || []);
const page = usePage();
const fr = computed(() => page.props.locale === 'fr');
const prefix = computed(() => fr.value ? '/fr' : '');
const text = (en, french) => fr.value ? french : en;
const dateLocale = computed(() => fr.value ? 'fr-FR' : 'en-GB');
const user = computed(() => page.props.auth?.user);
const candidate = computed(() => user.value?.is_candidate || user.value?.userable_type === 'student');
const ownsIt = computed(() => user.value?.is_admin || (props.internship.origin === 'native' && user.value?.userable_type === 'company' && user.value?.userable_id === props.internship.company?.id));
const external = computed(() => props.internship.application_mode === 'external');
const copied = ref(false);
const confirming = ref(false);
const notes = ref('');
const tracking = ref(false);
const reportOpen = ref(false);
const report = useForm({ reason: 'incorrect', details: '' });
const submitReport = () => report.post(`/opportunities/${props.internship.id}/report`, { preserveScroll: true, onSuccess: () => { report.reset(); reportOpen.value = false; } });
const formatDay = (date) => new Intl.DateTimeFormat(dateLocale.value, { dateStyle: 'long', timeZone: 'UTC' }).format(new Date(date));
const deadline = computed(() => {
    if (props.internship.expires_at) return new Intl.DateTimeFormat(dateLocale.value, { dateStyle: 'long', timeStyle: 'short', timeZone: 'Africa/Tunis' }).format(new Date(props.internship.expires_at)) + text(' (Tunisia time)', ' (heure de Tunisie)');
    if (props.internship.closing_date) return formatDay(props.internship.closing_date);
    return text('No deadline listed', 'Aucune date limite indiquée');
});
const workTypes = computed(() => fr.value ? { remote: 'À distance', hybrid: 'Hybride', onsite: 'Sur site', unknown: 'Non précisé' } : { remote: 'Remote', hybrid: 'Hybrid', onsite: 'Onsite', unknown: 'Not specified' });
const seniorityLabel = computed(() => ({ entry: text('Entry level', 'Débutant'), graduate: text('Graduate', 'Jeune diplômé'), mid: text('Mid level', 'Confirmé'), senior: 'Senior', lead: text('Lead', 'Responsable'), executive: text('Executive', 'Direction') }[props.internship.seniority] || props.internship.seniority));
const programLabel = computed(() => ({ pfe: 'PFE', summer: text('Summer internship', 'Stage d’été'), apprenticeship: text('Apprenticeship', 'Alternance'), graduate: text('Graduate programme', 'Programme jeunes diplômés'), other: text('Other programme', 'Autre programme') }[props.internship.program_type] || props.internship.program_type));
const employmentLabel = (type) => ({ FULL_TIME: text('Full time', 'Temps plein'), PART_TIME: text('Part time', 'Temps partiel'), CONTRACTOR: text('Contract / freelance', 'Contrat / freelance'), TEMPORARY: text('Temporary', 'Temporaire'), INTERN: text('Internship', 'Stage'), VOLUNTEER: text('Volunteer', 'Bénévolat'), PER_DIEM: text('Per diem', 'À la journée'), CONTRACT: text('Contract / freelance', 'Contrat / freelance'), INTERNSHIP: text('Internship', 'Stage'), OTHER: text('Other', 'Autre') }[String(type).toUpperCase().replaceAll(' ', '_').replaceAll('-', '_')] || type.replaceAll('_', ' ').toLowerCase());
const payLabel = computed(() => {
    const pay = props.internship.pay;
    if (!pay) return props.internship.compensation_status === 'unpaid' ? text('Unpaid', 'Non rémunéré') : text('Compensation not specified', 'Rémunération non précisée');
    const minimum = pay.min ?? pay.amount;
    const min = minimum == null ? null : Math.round(Number(minimum));
    const max = pay.max == null ? null : Math.round(Number(pay.max));
    const amount = min != null && max != null && min !== max ? `${min}–${max}` : min ?? max;
    const periods = fr.value ? { hour: 'heure', day: 'jour', week: 'semaine', month: 'mois', year: 'an' } : {};
    return `${amount ?? ''} ${pay.currency || text('(currency not specified)', '(devise non précisée)')}${pay.unit ? ` / ${periods[pay.unit] || pay.unit}` : ''}`;
});
const eligibility = computed(() => props.internship.remote_eligibility === 'eligible'
    ? text('The source explicitly permits work from Tunisia.', 'La source autorise explicitement le travail depuis la Tunisie.')
    : props.internship.remote_eligibility === 'restricted'
        ? text('The source lists location restrictions. Work from Tunisia is not confirmed as eligible.', 'La source indique des restrictions géographiques. Le travail depuis la Tunisie n’est pas confirmé.')
        : text('Eligibility to work from Tunisia is unknown. Confirm it with the employer before applying.', 'On ne sait pas si le travail depuis la Tunisie est possible. Vérifiez-le auprès de l’employeur avant de postuler.'));
const evidenceLabel = (value) => ({ yes: text('Stated by the employer or source', 'Indiqué par l’employeur ou la source'), no: text('Not offered according to the source', 'Non proposé selon la source') }[value] || text('Not specified', 'Non précisé'));
const save = () => toggleSaved(props.internship);
const saved = computed(() => user.value ? !!props.internship.liked : isSaved(props.internship.id));
const openedLabel = computed(() => {
    const date = openedAt(props.internship.id);
    return date ? new Intl.DateTimeFormat(dateLocale.value, { dateStyle: 'medium', timeZone: 'Africa/Tunis' }).format(new Date(date)) : '';
});
const trackError = ref('');
const track = () => {
    tracking.value = true;
    trackError.value = '';
    router.post(`/opportunities/${props.internship.id}/track`, { candidate_notes: notes.value }, {
        preserveScroll: true,
        onSuccess: () => { confirming.value = false; },
        onError: (errors) => { trackError.value = Object.values(errors)[0] || text('This could not be saved. Please try again.', 'Impossible d’enregistrer. Veuillez réessayer.'); },
        onFinish: () => { tracking.value = false; },
    });
};
const copyFailed = ref(false);
const copy = async () => {
    try { await navigator.clipboard.writeText(props.internship.public_url || window.location.href); copied.value = true; copyFailed.value = false; }
    catch { copied.value = false; copyFailed.value = true; }
};
const remove = () => {
    if (window.confirm(text('Remove this opportunity from public discovery? Existing application history will be retained.', 'Retirer cette opportunité de la recherche publique ? L’historique des candidatures sera conservé.'))) router.delete(`/internships/${props.internship.id}`);
};
