/p><a v-if="internship.is_open" href="#application-options" class="cta cta-primary w-full mt-5 lg:hidden">{{ text('View application options', 'Voir comment postuler') }}</a></header>
                <section class="bg-white border border-line rounded-2xl p-6 sm:p-8"><h2 class="font-display text-xl font-semibold mb-5">{{ text('About this opportunity', 'À propos de cette opportunité') }}</h2><div :lang="internship.language || undefined" dir="auto" class="whitespace-pre-line text-base text-slate-700 leading-8 break-words">{{ internship.description }}</div><div v-if="internship.skills?.length" class="mt-8 border-t border-line pt-6"><h2 class="font-display text-lg font-semibold mb-4">{{ text('Skills and expertise', 'Compétences') }}</h2><div class="flex flex-wrap gap-2"><span v-for="skill in internship.skills" :key="skill" class="bg-blue-50 text-blue-700 rounded-lg px-3 py-2 text-sm font-semibold">{{ skill }}</span></div></div><div v-if="internship.attachments?.length" class="mt-8 border-t border-line pt-6"><h2 class="font-display text-lg font-semibold mb-4">{{ text('Opportunity attachments', 'Pièces jointes') }}</h2><a v-for="attachment in internship.attachments" :key="attachment.url" :href="attachment.url" target="_blank" rel="noopener noreferrer" class="flex items-center gap-2 py-2 text-blue-700 break-all"><Download :size="18" />{{ attachment.name }}</a></div></section>
