                    <template v-if="ownsIt"><Link :href="`/internships/${internship.id}/edit`" class="cta cta-primary w-full">{{ text('Edit opportunity', 'Modifier l’opportunité') }}</Link><Link v-if="!external" :href="`/internships/${internship.id}/applications`" class="cta cta-secondary w-full mt-3">{{ text('Review applicants', 'Voir les candidats') }}</Link><button type="button" class="text-red-600 text-sm font-semibold mt-4 w-full" @click="remove">{{ text('Remove opportunity', 'Retirer l’opportunité') }}</button></template>
                    <template v-else>
